var n=`1228-picadillo-cubano`;var t=`world-1228`;var a=`CU`;var o=`central-america-caribbean`;var r=4;var s=40;var g={en:`Picadillo Cubano`,ua:`Пікадільйо по-кубинськи`};var l={en:`Picadillo Cubano is a dish from Cuba featuring ground beef, yellow onion, green bell pepper, garlic. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Пікадільйо по-кубинськи, страва кухні країни Куба з такими основними складниками: яловичий фарш, жовта цибуля, зелений солодкий перець, часник. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`ground-beef`,690,`g`],[`yellow-onion`,180,`g`],[`green-bell-pepper`,190,`g`],[`garlic`,5,`clove`],[`olive-oil`,40,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 25 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 25 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:25,i:[[`tomato`,430,`g`],[`ground-cumin`,6,`g`],[`dried-oregano`,5,`g`],[`beef-stock`,200,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:5,i:[[`green-olives`,100,`g`],[`raisin`,85,`g`]]}];var u={slug:n,id:t,country:`CU`,region:o,servings:4,minutes:40,title:g,text:l,steps:d};export{a as country,u as default,t as id,s as minutes,o as region,r as servings,n as slug,d as steps,l as text,g as title};